package com.nextaicommerce.platform.shipping;
import java.util.*;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.test.util.ReflectionTestUtils;import com.nextaicommerce.platform.sync.AmazonSpApiClient;import tools.jackson.databind.ObjectMapper;
class LocalAmazonShippingRecipientTest {
 final UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();final String order="114-1234567-1234567";final ObjectMapper json=new ObjectMapper();final OrderRecipientRepository repository=mock(OrderRecipientRepository.class);final AmazonSpApiClient amazon=mock(AmazonSpApiClient.class);final ShippingLabelCrypto crypto=new ShippingLabelCrypto(Base64.getEncoder().encodeToString(new byte[32]));OrderRecipientService service;OrderRecipientRepository.Command command;
 OrderRecipient sample(){return new OrderRecipient("Fixture","5551234567","123 Test St","","","Memphis","TN","38103","US","RESIDENTIAL");}
 OrderRecipientRepository.Stored encrypted(UUID tenant)throws Exception{var e=crypto.encrypt(json.writeValueAsBytes(sample()),OrderRecipientService.context(tenant,store,order));return new OrderRecipientRepository.Stored("AVAILABLE",e.payload(),e.nonce());}
 @BeforeEach void setup(){service=new OrderRecipientService(repository,crypto,json,amazon,false);ReflectionTestUtils.setField(service,"localShipping",true);command=new OrderRecipientRepository.Command(tenant,store,order,"ATVPDKIKX0DER",UUID.randomUUID());when(repository.claimLocalShippingRead(tenant,store,order)).thenReturn(command);}
 @Test void dedicatedFlagOffDoesNotReadDecryptOrFetch(){ReflectionTestUtils.setField(service,"localShipping",false);assertThat(service.localShipping(tenant,store,order).status()).isEqualTo("DISABLED");verifyNoInteractions(repository,amazon);}
 @Test void currentEncryptedCacheNeedsNoAmazonCall()throws Exception{when(repository.readCurrentLocalShipping(tenant,store,order)).thenReturn(encrypted(tenant));assertThat(service.localShipping(tenant,store,order).recipient()).isEqualTo(sample());verifyNoInteractions(amazon);verify(repository,never()).claimLocalShippingRead(any(),any(),any());}
 @Test void foreignContextCiphertextIsNeverExposed()throws Exception{when(repository.readCurrentLocalShipping(tenant,store,order)).thenReturn(encrypted(UUID.randomUUID()));assertThat(service.localShipping(tenant,store,order).status()).isEqualTo("UNAVAILABLE");verifyNoInteractions(amazon);}
 @Test void lostLeaseOrStaleSourceAfterFetchDoesNotReturnRecipient(){when(amazon.localShippingRecipient(tenant,store,"https://sellingpartnerapi-na.amazon.com",order)).thenReturn(sample());assertThat(service.localShipping(tenant,store,order).status()).isEqualTo("NOT_AVAILABLE");verify(repository).complete(eq(command),eq("AVAILABLE"),any());verify(repository,never()).enqueue(any(),any(),any());verify(repository,never()).claim(any());}
 @Test void missingCredentialsAndDeniedReadAreDistinctSafeStates(){when(amazon.localShippingRecipient(any(),any(),any(),any())).thenThrow(new IllegalStateException("Amazon credentials are not connected."));assertThat(service.localShipping(tenant,store,order).status()).isEqualTo("LOCAL_CONNECTION_REQUIRED");doThrow(new AmazonSpApiClient.AmazonApiException(403,null,"private response")).when(amazon).localShippingRecipient(any(),any(),any(),any());var view=service.localShipping(tenant,store,order);assertThat(view.status()).isEqualTo("ACCESS_DENIED");assertThat(view.toString()).doesNotContain("private");verify(repository).failed(command,true);verify(repository,never()).complete(any(),any(),any());}
 @Test void busyLeaseDoesNotIssueAnotherRead(){when(repository.claimLocalShippingRead(tenant,store,order)).thenReturn(null);assertThat(service.localShipping(tenant,store,order).status()).isEqualTo("NOT_AVAILABLE");verifyNoInteractions(amazon);}
}
